key:
eb3-${{ runner.os }}-${{ runner.arch }}-builder-${{ steps.electron-tools.outputs.eb }}  #computed-by: node -e '
  const l = require("./package-lock.json")
  const eb = l.packages["node_modules/electron-builder"].version
  if (!eb) process.exit(1)
  console.log("eb=" + eb)
' >> "$GITHUB_OUTPUT"

