${{ steps.playwright-cache-key.outputs.key }}  #computed-by: VERSION=$(awk '/^name = "playwright"/{f=1} f && /^version = /{gsub(/"/,"",$3); print $3; exit}' poetry.lock)
[ -n "$VERSION" ] || { echo 'Could not read the playwright version from poetry.lock'; exit 1; }
echo "key=$OS_ID-pw-$BROWSER-$VERSION" >> "$GITHUB_OUTPUT"

ingest-preds-pr${{ steps.pr.outputs.number }}-${{ hashFiles('models/**/*.yml') }}  #computed-by: gh api "repos/$GITHUB_REPOSITORY/pulls/$PR" > "$RUNNER_TEMP/pr.json"
jq -e --arg sha "$EXPECTED_SHA" '.state == "open" and .head.sha == $sha' "$RUNNER_TEMP/pr.json" > /dev/null || {
  echo "::error::PR #$PR is closed or its head differs from reviewed SHA $EXPECTED_SHA."
  exit 1
}
jq -r '"number=\(.number)", "changed_files=\(.changed_files)", "head_sha=\(.head.sha)", "head_repo=\(.head.repo.full_name)", "head_ref=\(.head.ref)"' "$RUNNER_TEMP/pr.json" >> "$GITHUB_OUTPUT"
